        1:return {16'(n/32'd5),ZIGZAG[6'(32'd1+n%32'd5)]};
        2:return {16'(n/32'd15),ZIGZAG[6'(32'd6+n%32'd15)]};
        3:return {16'(n/32'd43),ZIGZAG[6'(32'd21+n%32'd43)]};
